## solutions

#### breadth first (iterative)

```cpp
#include <queue>
#include <tuple>

std::vector<std::vector<std::string>> treeLevels(Node* root) {
  std::queue<std::tuple<Node*, int>> queue;
  if (root != nullptr) {
    queue.push(std::tuple { root, 0 });
  }

  std::vector<std::vector<std::string>> levels;

  while (queue.size() > 0) {
    auto [current, level] = queue.front();
    queue.pop();

    if (levels.size() == level) {
      levels.push_back(std::vector<std::string> { current->val });
    } else {
      levels[level].push_back(current->val);
    }

    if (current->left != nullptr) {
      queue.push(std::tuple { current->left, level + 1 });
    }

    if (current->right != nullptr) {
      queue.push(std::tuple { current->right, level + 1 });
    }
  }

  return levels;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)

#### depth first (recursive)

```cpp
void treeLevels(Node* root, std::vector<std::vector<std::string>> &levels, int level) {
  if (root == nullptr) {
    return;
  }

  if (level == levels.size()) {
    levels.push_back(std::vector<std::string> { root->val });
  } else {
    levels[level].push_back(root->val);
  }
  treeLevels(root->left, levels, level + 1);
  treeLevels(root->right, levels, level + 1);
}

std::vector<std::vector<std::string>> treeLevels(Node* root) {
  std::vector<std::vector<std::string>> levels;
  treeLevels(root, levels, 0);
  return levels;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)
